-- 🌟 99 noms : fiche n° 67 Al-Ahad (adulte + enfant) et verset « muhyî al-mawtâ » sur la fiche 60 — GÉNÉRÉ par
-- scripts/fiches-99-noms/al_ahad_27_11.py. À appliquer avec `supabase db query --linked -f` (JAMAIS `db push`). Relancer = sans effet.

update public.allah_names set fiche_adulte = $v${"nom_arabe": "الأَحَدُ", "translit": "Al-Ahad", "traduction": "L'Unique, le Seul, sans associé ni égal.", "provenance": "Coran (sourate Al-Ikhlâs, 112:1) et Sunna authentique.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Ahad signifie qu'Allah est absolument Unique, seul dans Sa divinité, Sa seigneurie, Ses noms et Ses attributs.\n\nIl n'a aucun associé, aucun égal, aucun semblable et personne ne Lui est comparable. Il est unique dans Sa perfection et rien dans Sa création ne Lui ressemble.\n\nCe nom exprime le fondement même du monothéisme : Allah seul mérite d'être adoré. Aucun être ne partage avec Lui Sa divinité ni Sa perfection.\n\nIl ne faut pas confondre l'unicité d'Allah avec une simple unité de nombre : Allah est unique d'une manière qui Lui est propre, sans pareil ni équivalent."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Adorer Allah seul, sans rien Lui associer.\n- Placer notre confiance en Lui : Il est notre seul Seigneur, et toutes nos demandes Lui sont adressées.\n- Ne rien comparer à Allah : aucune créature ne Lui ressemble.\n- Renforcer notre foi : le vrai monothéisme, c'est reconnaître l'unicité absolue d'Allah.\n- Être sincères : notre prière, nos invocations et notre adoration sont pour Allah seul."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "قُلْ هُوَ ٱللَّهُ أَحَدٌ", "traduction": "« Dis : Il est Allah, l'Unique. »", "ref": "Sourate Al-Ikhlâs, 112:1.", "degre": "coran", "texte": "Ce verset affirme directement l'unicité absolue d'Allah et contient le nom Al-Ahad."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Nous pouvons invoquer Allah par ce nom quand nous voulons :\n- affirmer notre foi en Son unicité ;\n- Lui demander de raffermir notre foi et notre attachement au tawhîd ;\n- Lui demander de nous préserver de toute forme d'association ;\n- Lui confier nos besoins en reconnaissant qu'Il est le seul Seigneur digne d'adoration.\n\nSans lui attribuer un moment particulier, un nombre de répétitions ou un mérite qui ne seraient pas établis."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Ahad, Toi l'Unique, raffermis mon cœur dans la foi, préserve-moi de toute forme d'association et aide-moi à T'adorer sincèrement, sans rien T'associer. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "prophetique", "titre": "Invocation entendue par le Prophète ﷺ", "arabe": "اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ، الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ", "phonetique": null, "traduction": "« Ô Allah ! Je Te demande en attestant que Tu es Allah, qu'il n'y a aucune divinité digne d'être adorée en dehors de Toi, l'Unique, Celui dont toutes les créatures ont besoin, Celui qui n'a pas engendré et n'a pas été engendré, et auquel nul n'est égal. »", "ref": "Sunan Abî Dâwûd 1493 et Jâmi' At-Tirmidhî 3475, d'après Burayda ibn Al-Husayb (qu'Allah l'agrée).", "degre": "sahih", "texte": "Avis sur son authenticité : At-Tirmidhî : hasan gharîb. Al-Albânî : sahih. Ahmad Châkir : sahih. Zubair 'Alî Zaï : sahih. Pour Abû Dâwûd 1493 : Al-Albânî et Chou'ayb Al-Arna'ût : sahih.", "note": "Précision importante : dans ce récit, le Prophète ﷺ entend un homme prononcer cette invocation, puis il dit que cet homme a invoqué Allah par Son Nom suprême. Ce n'est donc pas une invocation que le Prophète ﷺ aurait lui-même prononcée.", "divergence": "At-Tirmidhî : hasan gharîb. Al-Albânî : sahih. Ahmad Châkir : sahih. Zubair 'Alî Zaï : sahih. Pour Abû Dâwûd 1493 : Al-Albânî et Chou'ayb Al-Arna'ût : sahih."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "CORAN", "texte": "Statut : établi par le Coran et attesté dans la Sunna.\n\nLe nom Al-Ahad apparaît dans le Coran, sourate Al-Ikhlâs, verset 1.\n\nIl figure aussi dans l'invocation rapportée par Abû Dâwûd (1493) et At-Tirmidhî (3475), jugée authentique par des spécialistes du hadith.\n\nSon sens est fondamental dans la croyance sunnite : Allah est Unique et rien ne Lui est comparable."}], "numero_source": null}$v$::jsonb, fiche_enfant = $v${"nom_arabe": "الأَحَدُ", "translit": "Al-Ahad", "statut": "etabli", "sens": "Allah est l'Unique : personne n'est comme Lui.", "comme": "Quand je récite la sourate Al-Ikhlâs, je dis qu'Allah est Unique.", "faire": "J'adore Allah seul et je fais mes prières pour Lui.", "dire": "Qoul houwa llâhou ahad.", "dire_type": "texte", "dire_arabe": "قُلْ هُوَ ٱللَّهُ أَحَدٌ", "dire_traduction": "« Dis : Il est Allah, l'Unique. »", "dire_ref": "Coran, sourate Al-Ikhlâs (112), verset 1.", "dire_degre": "coran", "prudence": null, "a_relire": true}$v$::jsonb where display_order = 67 and fiche_adulte is null;
update public.allah_names set fiche_adulte = $v${"nom_arabe": "الْمُحْيِي", "translit": "Al-Muhyî", "traduction": "Celui qui donne la vie et qui ressuscite les morts.", "provenance": "Coran — Allah donne la vie (action clairement attestée) ; forme nominale « Al-Muhyî » à préciser.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Muhyî désigne Allah comme Celui qui donne la vie.\n\nIl est Celui qui donne l'existence aux êtres vivants, qui fait sortir la vie de ce qui paraît inerte et qui ressuscitera les morts au Jour dernier.\n\nLa vie appartient à Allah et dépend entièrement de Sa volonté.\n\nCe nom nous rappelle que notre existence est un bienfait immense et que nous devons utiliser notre vie pour accomplir ce qui plaît à notre Créateur."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah est Celui qui donne la vie.\n- Être reconnaissants pour le bienfait de l'existence.\n- Se rappeler que la vie terrestre est temporaire.\n- Préparer notre retour vers Allah.\n- Ne jamais désespérer de Sa puissance."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "فَٱنظُرْ إِلَىٰٓ ءَاثَٰرِ رَحْمَتِ ٱللَّهِ كَيْفَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ ۚ إِنَّ ذَٰلِكَ لَمُحْىِ ٱلْمَوْتَىٰ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ", "traduction": "« Regarde donc les effets de la miséricorde d'Allah, comment Il redonne la vie à la terre après sa mort. C'est Lui qui fait revivre les morts, et Il est Omnipotent. »", "ref": "Sourate Ar-Rûm, 30:50.", "degre": "coran", "texte": "Le Coran dit « لَمُحْىِ ٱلْمَوْتَىٰ » (muhyî al-mawtâ : « Celui qui fait revivre les morts ») : le mot est suivi d'un complément. C'est pourquoi la forme seule « Al-Muhyî » est discutée."}, {"type": "preuve", "titre": "Autre verset", "arabe": "إِنَّ ٱلَّذِىٓ أَحْيَاهَا لَمُحْىِ ٱلْمَوْتَىٰٓ ۚ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ", "traduction": "« Celui qui lui redonne la vie est certes Celui qui fera revivre les morts, car Il est Omnipotent. »", "ref": "Sourate Fussilat, 41:39 (fin du verset).", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de vivifier notre cœur par la foi, de nous guider et de nous accorder une vie consacrée à Son obéissance."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Muhyî, donne vie à mon cœur par la foi, éloigne-moi de ce qui m'éloigne de Toi et aide-moi à consacrer ma vie à ce qui Te satisfait. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "FORME NOMINALE À PRÉCISER", "texte": "Le sens est directement confirmé par le Coran : Allah donne la vie et fait revivre les morts.\n\nLe statut de la forme « Al-Muhyî » comme nom indépendant dépend de la méthode retenue pour établir les noms divins.\n\nCette précision ne remet jamais en cause le fait qu'Allah donne la vie."}], "numero_source": 60}$v$::jsonb where display_order = 60 and fiche_adulte = $v${"nom_arabe": "الْمُحْيِي", "translit": "Al-Muhyî", "traduction": "Celui qui donne la vie et qui ressuscite les morts.", "provenance": "Coran — Allah donne la vie (action clairement attestée) ; forme nominale « Al-Muhyî » à préciser.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Explication", "texte": "Al-Muhyî désigne Allah comme Celui qui donne la vie.\n\nIl est Celui qui donne l'existence aux êtres vivants, qui fait sortir la vie de ce qui paraît inerte et qui ressuscitera les morts au Jour dernier.\n\nLa vie appartient à Allah et dépend entièrement de Sa volonté.\n\nCe nom nous rappelle que notre existence est un bienfait immense et que nous devons utiliser notre vie pour accomplir ce qui plaît à notre Créateur."}, {"type": "texte", "titre": "Ce que ce nom nous enseigne", "texte": "- Reconnaître qu'Allah est Celui qui donne la vie.\n- Être reconnaissants pour le bienfait de l'existence.\n- Se rappeler que la vie terrestre est temporaire.\n- Préparer notre retour vers Allah.\n- Ne jamais désespérer de Sa puissance."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": null, "traduction": "« Regarde donc les effets de la miséricorde d'Allah, comment Il redonne la vie à la terre après sa mort. C'est Lui qui fait revivre les morts, et Il est Omnipotent. »", "ref": "Sourate Ar-Rûm, 30:50.", "degre": "coran", "texte": "Autre référence : Sourate Fussilat, 41:39."}, {"type": "texte", "titre": "Quand invoquer Allah par ce nom", "texte": "Lorsque nous demandons à Allah de vivifier notre cœur par la foi, de nous guider et de nous accorder une vie consacrée à Son obéissance."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Muhyî, donne vie à mon cœur par la foi, éloigne-moi de ce qui m'éloigne de Toi et aide-moi à consacrer ma vie à ce qui Te satisfait. »", "note": "Cette formulation est une invocation personnelle, et non une formule prophétique spécifique rapportée."}, {"type": "authenticite", "titre": "Authenticité et provenance", "badge": "FORME NOMINALE À PRÉCISER", "texte": "Le sens est directement confirmé par le Coran : Allah donne la vie et fait revivre les morts.\n\nLe statut de la forme « Al-Muhyî » comme nom indépendant dépend de la méthode retenue pour établir les noms divins.\n\nCette précision ne remet jamais en cause le fait qu'Allah donne la vie."}], "numero_source": 60}$v$::jsonb;

